"""The general (boxed) path as the safety net (branch safetynet), against CPython 3.12.

Programs the typed path refuses must build on the general path and print what CPython prints. Each program below
is built with the general path forced (`pyc.py --general-only` on the Python surface text) and run against CPython:
stdout and the exit code must match (stderr too where the program writes there on purpose).

S1_slices                slice objects: a slice of an instance reaches __getitem__ / __setitem__ / __delitem__, slice(), indices(), list slice assignment and deletion
S1_slice_getitem         slices of an instance, slice objects as values
S2_bytes                 bytes and bytearray: literals, methods, codecs, errors, stdin/stdout buffers
S2_bytes_io              sys.stdin.buffer / sys.stdout.buffer / open(.., "rb") through read_bytes, sys.argv
S2_translate             bytes.translate / maketrans, join of a dict's values
S3_format                format specs of every standard type, computed specs, % at run time
S4_generators            generator functions: yield, yield from, send, generator methods, try/finally
S4_generators_gc         generators left unfinished, nested generators and collections while they run
S5_predicates            str.isalpha / isalnum / isupper / islower / istitle over Unicode
S5_decimal_pred          str.isdecimal / isnumeric
S6_user_methods          a class with split / strip / ... methods: the str fast paths do not take its results, a staticmethod called on the class
S6_split_pool            `xs = obj.split()` of a user class (was read as a str split)
S7_class_value           a class called through a variable (`make = Fenwick; make(data)`)
S8_type_aliases          module-level type aliases and TypeVar
S9_key_functions         key= / map() / reduce() functions as values, cmp_to_key, map and zip of 3+
S10_defaultdict          defaultdict with a factory function, held in attributes and passed around
S11_nested_defaults      nested defs with defaults, *args and keyword-only parameters
S12_stderr               print(..., file=sys.stderr / sys.stdout, flush=)
S13_starred              starred arguments of print and of set union / intersection / difference
S14_notimplemented       NotImplemented: reflected operators, equality, ordering
S15_attrs                getattr / hasattr / setattr / vars / callable, builtins as values
S16_exceptions           exception objects of the program's classes: args, __init__, __str__, e.args
S16_exceptions_methods   methods and isinstance of exception objects, an uncaught one
S17_dataclass_eq         a @dataclass compares by its fields (was identity), a frozen one hashes
S19_properties           @property getters and setters, @classmethod, Generic bases, annotated class attributes
S20_int_methods          int.bit_length / bit_count / is_integer, float.is_integer
S18_double_read          a file read twice inside one with: the second read is empty (both paths)
G1  the default build takes a typed-path boundary refusal (sys.argv, sys.stdout.buffer) to the general path
G2  a class held in a variable is constructed (the regression of the nested-fn merge)
G3  the tuple pass's int-to-float widening stays an int on the general path
G4  next() of a generator expression stops at its first element
"""
import os
import shutil
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parent
PYC = ROOT / 'python' / 'pkg-v12' / 'pyc.py'
HAVE_CC = shutil.which('gcc') is not None
sys.path.insert(0, str(ROOT))


def surface(text):
    import ail_syntax
    return ail_syntax.fold_constants(ail_syntax.python_surface(text))


def build_general(directory, text, name):
    source, exe = Path(directory, name + '_g.ail'), Path(directory, name + '_g')
    source.write_text(surface(text), encoding='utf-8')
    env = dict(os.environ, AIL_IR='0', AIL_NO_CACHE='1', AIL_SURFACE='python')
    env.pop('AIL_NO_GENERAL', None)
    res = subprocess.run([sys.executable, '-B', str(PYC), exe.name, '--file', source.name, '--general-only'],
                         cwd=directory, capture_output=True, text=True, timeout=900, env=env)
    return res, exe


def build_default(directory, text, name):
    source, exe = Path(directory, name + '.py'), Path(directory, name + '_d')
    source.write_text(text, encoding='utf-8')
    env = dict(os.environ, AIL_NO_CACHE='1', AIL_IR='0')
    env.pop('AIL_NO_GENERAL', None)
    res = subprocess.run([sys.executable, '-B', str(ROOT / 'ail_chatgpt.py'), 'compile', source.name, '--syntax',
                          'python', '-o', exe.name], cwd=directory, capture_output=True, text=True, timeout=900, env=env)
    return res, exe


def run(cmd, directory, stdin):
    return subprocess.run(cmd, cwd=directory, capture_output=True, timeout=300, input=stdin.encode('utf-8'))


